out={"$comment":"W05 contract authority matrix for the Forge-owned stack. Machine-checked by apps/forge-web/test/unit/w05-authority-matrix.test.ts (every state-changing ABI function must be classified) and test/integration/w05-authority-enforcement.test.ts (every 'owner'/'forge-factory' entry is refused for a stranger). Ownership: every listed Ownable contract is Ownable2Step; renounceOwnership is disabled except where noted.","version":1,"contracts":{}}
for c,fns in spec.items():
    abi=json.load(open(f"{ROOT}/out/forge/{c}.sol/{c}.json"))["abi"]
    out["contracts"][c]={"ownership":"Ownable2Step" if any(x.get("name")=="acceptOwnership" for x in abi) else "none (immutable wiring)","upgradeable":False,"functions":[]}
    for sig,(acc,cat,tl,em,ev,note) in fns.items():
        out["contracts"][c]["functions"].append({"signature":sig,"access":acc,"category":cat,"timelock":tl,"emergency":em,"monitoringEvents":ev,"note":note})
json.dump(out,open(sys.argv[2],"w"),indent=1)
print("ok", sum(len(v["functions"]) for v in out["contracts"].values()))
